-- 📚 꼭집 주거 사전 — 예비입주자 순번·유효기간 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.7초 · 결과:
-- {"anns": 103, "by_std": {"SH 고유": 1, "공공임대(6·10·50년)": 4, "국민임대": 43, "매입임대": 43, "영구임대": 4, "행복주택": 5, "행복주택(신혼희망)": 3}, "ex": ["SH_311349", "SH_310653", "SH_310650", "21390_부산광역시_사하구"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where '예비입주자 유효기간·순번'=cls),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='예비입주자 유효기간·순번' group by 1)q),'ex',(select json_agg(i) from(select distinct announcement_id i from y where '예비입주자 유효기간·순번'=cls order by 1 desc limit 4)q))j;
